import 'package:flutter/material.dart';
import 'package:waveform_recorder/waveform_recorder.dart';

class RecorderExample extends StatefulWidget {
  const RecorderExample({super.key});

  @override
  State<RecorderExample> createState() => _RecorderExampleState();
}

class _RecorderExampleState extends State<RecorderExample> {
  final _waveController = WaveformRecorderController();

  @override
  void dispose() {
    _waveController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => Scaffold(
        body: Center(
          child: _waveController.isRecording
              ? WaveformRecorder(
                  height: 48,
                  controller: _waveController,
                )
              : ElevatedButton(
                  onPressed: () => _waveController.startRecording(),
                  child: const Text('Start Recording'),
                ),
        ),
      );
}
